    "docCode": "FR-DPI-010",
    "title": "PROCÉDURE DE GESTION DES DONNÉES PERSONNELLES ET DES INCIDENTS FASOFREE",
    "version": "0.9",
    "statut": "brouillon-avocat",
    "date": "2026-09-27",
